        LinearLayout header=new LinearLayout(activity);header.setGravity(Gravity.CENTER_VERTICAL);PlayerIconButton close=icon(R.drawable.player_chevron_down,"收起播放页",false);header.addView(close,new LinearLayout.LayoutParams(dp(48),dp(48)));close.setOnClickListener(v->dismiss());
        LinearLayout info=new LinearLayout(activity);info.setOrientation(LinearLayout.VERTICAL);info.setGravity(Gravity.CENTER);title=label(16,Color.WHITE);title.setTypeface(Typeface.DEFAULT,Typeface.BOLD);title.setGravity(Gravity.CENTER);title.setSingleLine(true);artist=label(11,0xffd6e0e4);artist.setGravity(Gravity.CENTER);artist.setSingleLine(true);source=label(9,0xffbccbd1);source.setGravity(Gravity.CENTER);source.setSingleLine(true);info.addView(title,new LinearLayout.LayoutParams(-1,dp(20)));info.addView(artist,new LinearLayout.LayoutParams(-1,dp(15)));info.addView(source,new LinearLayout.LayoutParams(-1,dp(12)));header.addView(info,new LinearLayout.LayoutParams(0,dp(48),1));
