        body=new Body(activity);cover=new TurntableView(activity);cover.setMotion(!reduceMotion);cover.setContentDescription("唱片封面，点按打开歌词，左右滑动切歌");cover.setClickable(true);cover.setOnClickListener(v->host.lyrics());installCoverGesture();body.addView(cover);
